# 14 — Vendors
def browse_vendor(name,ini,vtype,rating,reviews,exp,jobs,cats,loc,availability='Available this week',tone='vendor'):
    return f'''<article class="card vendor-card" data-row data-type="{vtype}" data-category="{cats.split(',')[0]}" data-rating="{rating}" data-experience="{exp}" data-location="Ranchi" data-search="{name} {vtype} {cats} {loc}"><div class="vendor-top">{avatar(ini,'lg '+tone)}<div class="vendor-meta"><h3>{name} <span class="verified">{I('check')}</span></h3><div class="meta-line"><span>{vtype}</span><span>•</span><span class="rating"><span class="star">★</span>{rating} ({reviews})</span></div><div class="small muted" style="margin-top:4px">{I('map')} {loc}</div></div></div><div class="vendor-stats"><div class="vendor-stat"><strong>{exp} yrs</strong><span>Experience</span></div><div class="vendor-stat"><strong>{jobs}</strong><span>Completed jobs</span></div><div class="vendor-stat"><strong>{rating}</strong><span>Rating</span></div></div><div class="chips">{''.join(f'<span class="chip">{c.strip()}</span>' for c in cats.split(','))}</div><div class="price-row"><span class="availability">● {availability}</span><span class="small muted">Usually replies in 20 min</span></div><div class="vendor-actions"><a class="btn btn-secondary" href="details.html">View Profile</a><a class="btn btn-primary" href="../messages/chat.html">{I('chat')} Chat</a></div></article>'''

