write('support/create-complaint.html','Raise a Complaint','support-create-complaint',f'''
<div class="page-head"><div><h1>Raise a Complaint</h1><p>Report a vendor, account or platform issue. Include enough detail for the support team to investigate.</p></div><a class="btn btn-secondary" href="complaints.html">Cancel</a></div><div class="layout-main"><section class="card form-card"><form class="needs-validation" data-success-target="complaint-success"><div class="form-section"><div class="form-grid"><div class="field"><label>Related Job / Quick Service <span class="required">*</span></label><select class="select" required><option value="">Select related item</option><option>JOB-2026-0438 · Full House Renovation</option><option>QS-2026-0819 · AC cooling issue</option><option>Account / no related item</option></select></div><div class="field"><label>Complaint category <span class="required">*</span></label><select class="select" required><option value="">Select category</option><option>Vendor conduct</option><option>Quick Service</option><option>Job or quotation</option><option>Account</option><option>Platform issue</option></select></div><div class="field full"><label>Subject <span class="required">*</span></label><input class="input" required placeholder="Short summary of the issue"></div><div class="field full"><label>Description <span class="required">*</span></label><textarea class="textarea" required minlength="30" placeholder="Describe what happened, when it happened, who was involved and the outcome you expect..."></textarea></div><div class="field full"><label>Upload evidence</label>{upload('complaint-files','image/*,.pdf,.doc,.docx','Add images or documents','JPG, PNG, PDF or DOC up to 10 MB')}</div><div class="field"><label>Priority <span class="required">*</span></label><select class="select" required><option>Medium</option><option>Low</option><option>High</option><option>Urgent — safety concern</option></select></div></div></div><div class="form-actions"><a class="btn btn-secondary" href="complaints.html">Cancel</a><button class="btn btn-primary" type="submit">{I('send')} Submit Complaint</button></div></form></section><aside class="stack"><div class="callout warning">{I('alert')}<div><strong>Emergency or immediate danger?</strong>Contact local emergency services. Fixora support cannot provide emergency response.</div></div><section class="card"><div class="card-head"><h3>What happens next?</h3></div><div class="card-body timeline"><div class="timeline-item"><span class="timeline-dot"></span><h4>We review your report</h4><p>Usually within one business day.</p></div><div class="timeline-item"><span class="timeline-dot"></span><h4>Support may ask questions</h4><p>Reply in the complaint conversation.</p></div><div class="timeline-item"><span class="timeline-dot"></span><h4>Resolution is recorded</h4><p>You will receive a notification.</p></div></div></section></aside></div><section class="card success-panel" id="complaint-success" hidden><span class="success-icon">{I('check')}</span><h2>Complaint submitted</h2><p>Support has received your complaint and will review it shortly.</p><div class="success-summary"><div class="info-item"><span class="info-label">Complaint ID</span><strong>CMP-2026-0191</strong></div><div class="info-item"><span class="info-label">Status</span>{badge('Open','open')}</div><div class="info-item"><span class="info-label">Submitted</span><strong>20 Aug 2026, 11:48 AM</strong></div></div><a class="btn btn-primary" href="complaint-details.html">View Complaint</a></section>
''')

