channels=[('Quick Service notifications','Vendor responses, selection and status changes',1,1,1),('Job notifications','Bids, job status and work assignment updates',1,1,1),('Quotation notifications','New and withdrawn vendor quotations',1,0,1),('Vendor notifications','Selection, availability and profile updates',1,0,1),('Message notifications','New vendor messages and chat attachments',1,1,1),('System notifications','Security, policy and platform announcements',1,0,1)]
channel_html='<div class="channel-grid"><div></div><div class="channel-head">Email</div><div class="channel-head">SMS</div><div class="channel-head">Push</div>'
for title,desc,e,s,p in channels:
    channel_html+=f'''<div><strong class="small">{title}</strong><div class="tiny muted">{desc}</div></div><div><label class="toggle"><input type="checkbox" {'checked' if e else ''}><span class="toggle-slider"></span></label></div><div><label class="toggle"><input type="checkbox" {'checked' if s else ''}><span class="toggle-slider"></span></label></div><div><label class="toggle"><input type="checkbox" {'checked' if p else ''}><span class="toggle-slider"></span></label></div>'''
channel_html+='</div>'
write('settings/notifications.html','Notification Settings','setting-notifications',f'''
<div class="page-head"><div><h1>Notification Settings</h1><p>Choose which updates you receive and where you receive them.</p></div><button class="btn btn-primary" data-toast="Preferences saved" data-toast-message="Your notification settings have been updated.">{I('check')} Save Preferences</button></div><div class="layout-main" style="grid-template-columns:250px minmax(0,1fr)">{settings_nav}<div class="stack"><section class="card"><div class="card-head"><div><h2>Notification Channels</h2><p>Set Email, SMS and Push preferences by update type.</p></div></div><div class="card-body" style="padding-top:6px">{channel_html}</div><div class="card-footer small muted">Important security and legal notices may still be delivered regardless of your marketing preferences.</div></section><section class="card"><div class="card-head"><h2>Quiet Hours</h2></div><div class="card-body"><div class="setting-row"><div><h4>Pause non-urgent push notifications</h4><p>Messages and critical work updates will still be delivered.</p></div><label class="toggle"><input type="checkbox"><span class="toggle-slider"></span></label></div><div class="form-grid" style="margin-top:15px"><div class="field"><label>From</label><input class="input" type="time" value="22:00"></div><div class="field"><label>Until</label><input class="input" type="time" value="07:00"></div></div></div></section></div></div>
''')

